 {
  "turns": [
    {
      "speaker": "agent",
      "text": "Thank you for calling Nimbus Telecom. My name is Sana. How can I help you today?",
      "tags": [
        "greeting"
      ]
    },
    {
      "speaker": "customer",
      "text": "Hi Sana, I'm Sneha Wilson. I've been having a lot of trouble with my phone. It keeps restarting randomly and I can't get any work done.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I am sorry to hear that your device is causing you so much trouble, Ms. Wilson. I can certainly look into this for you.",
      "tags": [
        "empathy"
      ]
    },
    {
      "speaker": "customer",
      "text": "I just want it fixed. It's incredibly frustrating.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I understand. Before we dive into the account details, could you please provide me with your account number?",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "Yes, my account number is 13559020.",
      "tags": [
        "identity_verification"
      ]
    },
    {
      "speaker": "agent",
      "text": "Thank you. And just to confirm, is the phone number associated with the account 91068 52307?",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "That is correct.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "Thank you for verifying that. I've checked the system and it looks like this might be a hardware failure. I'm going to escalate this to our technical hardware team for a deeper analysis.",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "Will they be able to fix it quickly?",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "They are the experts in this area. I will book a device check for you at our nearest service center so they can examine the hardware physically.",
      "tags": [
        "action:device_fix"
      ]
    },
    {
      "speaker": "customer",
      "text": "Okay, that sounds like a plan.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "Is there anything else I can assist you with today? To recap, I have escalated your case to the hardware team and booked your device check. Thank you for calling Nimbus Telecom, and have a great day. Goodbye.",
      "tags": [
        "closure"
      ]
    }
  ]
}
